import React, { useState, useMemo, useEffect } from 'react';
import { supabase, supabaseConfigurado } from './supabaseClient';
import { Plus, X, Filter as FilterIcon, ChevronLeft, ChevronRight, ChevronDown, Calendar as CalendarIcon, Wallet, LayoutGrid, Trash2, Pencil } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const LOGO_SRC = 'data:image/png;base64,';

/* ---------- Constantes ---------- */
const ETAPAS = ['Briefing', 'Roteiro', 'Gravação', 'Edição', 'Revisão', 'Entrega'];
const MESES = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const DIAS_SEMANA = ['D', 'S', 'T', 'Q', 'Q', 'S', 'S'];
const IMPOSTO_NF = 0.06;

const STATUS = {
  atencao: { label: 'Atenção', color: '#E63946' },
  andamento: { label: 'Em andamento', color: '#F5C518' },
  aguardando: { label: 'Aguardando cliente', color: '#8A8F98' },
  concluido: { label: 'Concluído', color: '#2ECC71' },
};

const STATUS_FIN = {
  pago: { label: 'Pago', color: '#2ECC71' },
  pendente: { label: 'Pendente', color: '#F5C518' },
  atrasado: { label: 'Atrasado', color: '#E63946' },
};

const TIPO_EVENTO = {
  briefing: { label: 'Briefing', color: '#8A8F98' },
  gravacao: { label: 'Gravação', color: '#F5C518' },
  entrega: { label: 'Entrega', color: '#E63946' },
  pagamento: { label: 'Pagamento', color: '#2ECC71' },
};
const TIPO_EVENTO_FORM = Object.fromEntries(Object.entries(TIPO_EVENTO).filter(([key]) => key !== 'pagamento'));

/* ---------- Dados ---------- */
const seedDemandas = [];

const seedFinancas = [];

const seedGastos = [];

const HOJE = new Date();
HOJE.setHours(0, 0, 0, 0);
const moeda = (v) => v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

function diasRestantes(data) {
  return Math.round((new Date(data + 'T00:00:00') - HOJE) / 86400000);
}
function prazoLabel(dias) {
  if (dias < 0) return `Atrasado há ${Math.abs(dias)} dia${Math.abs(dias) === 1 ? '' : 's'}`;
  if (dias === 0) return 'Hoje';
  if (dias === 1) return 'Amanhã';
  return `Faltam ${dias} dias`;
}
function gerarDias(ano, mes) {
  const primeiro = new Date(ano, mes, 1);
  const ultimo = new Date(ano, mes + 1, 0);
  const dias = [];
  for (let i = 0; i < primeiro.getDay(); i++) dias.push(null);
  for (let d = 1; d <= ultimo.getDate(); d++) dias.push(new Date(ano, mes, d));
  return dias;
}
function chaveData(d) { return d.toISOString().slice(0, 10); }
function corTexto(hex) {
  const c = (hex || '#000000').replace('#', '');
  const r = parseInt(c.substring(0, 2), 16), g = parseInt(c.substring(2, 4), 16), b = parseInt(c.substring(4, 6), 16);
  const luminancia = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminancia > 0.6 ? '#0A0A0A' : '#FFFFFF';
}
function ordenarEventosDia(eventos) {
  return [...eventos].sort((a, b) => {
    const ta = a.diaTodo === false ? (a.horaInicio || '23:59') : '00:00';
    const tb = b.diaTodo === false ? (b.horaInicio || '23:59') : '00:00';
    return ta.localeCompare(tb);
  });
}
function statusFinanceiro(f) {
  if (f.pago) return 'pago';
  return diasRestantes(f.dataPagamento) < 0 ? 'atrasado' : 'pendente';
}
function valorLiquidoTrabalho(bruto, comNF) { return comNF ? bruto * (1 - IMPOSTO_NF) : bruto; }
function mesChave(data) {
  const d = new Date(data + 'T00:00:00');
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}
function mesLabelCurto(chave) {
  const [ano, mes] = chave.split('-');
  return `${MESES[Number(mes) - 1].slice(0, 3).toUpperCase()}/${ano.slice(2)}`;
}

function mapDemandaDoBanco(row) {
  return {
    id: row.id,
    cliente: row.cliente,
    projeto: row.projeto,
    etapa: row.etapa,
    prazo: row.prazo,
    status: row.status,
    dataGravacao: row.data_gravacao,
    datasGravacao: row.datas_gravacao || [],
    valor: Number(row.valor),
    comNF: row.com_nf,
  };
}
function mapFinancaDoBanco(row) {
  return {
    id: row.id,
    cliente: row.cliente,
    projeto: row.projeto,
    valor: Number(row.valor),
    valorBruto: row.valor_bruto != null ? Number(row.valor_bruto) : Number(row.valor),
    comNF: row.com_nf,
    dataTrabalho: row.data_trabalho,
    dataPagamento: row.data_pagamento,
    pago: row.pago,
    origemDemandaId: row.origem_demanda_id,
  };
}
function mapGastoDoBanco(row) {
  return {
    id: row.id,
    projeto: row.projeto,
    cliente: row.cliente,
    descricao: row.descricao,
    valor: Number(row.valor),
    data: row.data,
  };
}

const emptyDemanda = { cliente: '', projeto: '', etapa: ETAPAS[0], prazo: '', status: 'andamento', dataGravacao: null, datasGravacao: [], valor: '', comNF: false, dataPagamento: '' };
const emptyFinanca = { cliente: '', projeto: '', valor: '', dataTrabalho: '', dataPagamento: '', pago: false };
const emptyGasto = { projeto: '', cliente: '', descricao: '', valor: '', data: '' };

/* ---------- Tela: Login ---------- */
function TelaLogin() {
  const [modo, setModo] = useState('entrar'); // 'entrar' | 'cadastrar'
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');
  const [erro, setErro] = useState('');
  const [mensagem, setMensagem] = useState('');
  const [carregando, setCarregando] = useState(false);

  async function enviar(e) {
    e.preventDefault();
    setErro('');
    setMensagem('');
    setCarregando(true);

    if (modo === 'entrar') {
      const { error } = await supabase.auth.signInWithPassword({ email, password: senha });
      if (error) setErro(error.message === 'Invalid login credentials' ? 'E-mail ou senha incorretos.' : error.message);
    } else {
      const { data, error } = await supabase.auth.signUp({ email, password: senha });
      if (error) {
        setErro(error.message);
      } else if (data.user && !data.session) {
        setMensagem('Conta criada! Verifique seu e-mail para confirmar antes de entrar.');
      }
    }
    setCarregando(false);
  }

  return (
    <div style={{ background: '#000000', minHeight: '100vh', color: '#EDEDED', fontFamily: "'Inter', sans-serif" }} className="flex items-center justify-center p-5">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600;700&family=Inter:wght@400;500;600;700&display=swap');
        .mono { font-family: 'IBM Plex Mono', monospace; }
        input { background: #141414; border: 1px solid #262626; color: #EDEDED; font-family: 'Inter', sans-serif; }
        input:focus { outline: 2px solid #F5C518; outline-offset: 1px; }
        .focusable:focus-visible { outline: 2px solid #F5C518; outline-offset: 2px; }
      `}</style>
      <form onSubmit={enviar} className="w-full max-w-xs rounded-lg p-6" style={{ background: '#141414', border: '1px solid #262626' }}>
        <div className="flex flex-col items-center gap-3 mb-6">
          <img src={LOGO_SRC} alt="Norman" style={{ width: 64, height: 64, borderRadius: '9999px' }} />
          <div className="text-center">
            <div className="mono text-xs tracking-widest" style={{ color: '#9A9A9A' }}>PAINEL DO DIRETOR</div>
            <h1 className="mono text-lg font-semibold">Norman Film Crew</h1>
          </div>
        </div>

        <div className="flex gap-1 p-1 rounded mb-4" style={{ background: '#0A0A0A', border: '1px solid #262626' }}>
          <button
            type="button"
            onClick={() => { setModo('entrar'); setErro(''); setMensagem(''); }}
            className="flex-1 mono text-xs font-semibold py-1.5 rounded"
            style={{ background: modo === 'entrar' ? '#F5C518' : 'transparent', color: modo === 'entrar' ? '#0A0A0A' : '#9A9A9A' }}
          >
            Entrar
          </button>
          <button
            type="button"
            onClick={() => { setModo('cadastrar'); setErro(''); setMensagem(''); }}
            className="flex-1 mono text-xs font-semibold py-1.5 rounded"
            style={{ background: modo === 'cadastrar' ? '#F5C518' : 'transparent', color: modo === 'cadastrar' ? '#0A0A0A' : '#9A9A9A' }}
          >
            Criar conta
          </button>
        </div>

        <div className="flex flex-col gap-3">
          <input required type="email" placeholder="E-mail" value={email} onChange={(e) => setEmail(e.target.value)} className="focusable rounded px-3 py-2 text-sm" />
          <input required type="password" placeholder="Senha (mín. 6 caracteres)" value={senha} onChange={(e) => setSenha(e.target.value)} minLength={6} className="focusable rounded px-3 py-2 text-sm" />
          {erro && <p className="mono text-xs" style={{ color: '#E63946' }}>{erro}</p>}
          {mensagem && <p className="mono text-xs" style={{ color: '#2ECC71' }}>{mensagem}</p>}
          <button type="submit" disabled={carregando} className="focusable mono text-sm font-semibold rounded py-2 mt-1" style={{ background: '#F5C518', color: '#0A0A0A', opacity: carregando ? 0.6 : 1 }}>
            {carregando ? 'Aguarde...' : modo === 'entrar' ? 'Entrar' : 'Criar conta'}
          </button>
        </div>
      </form>
    </div>
  );
}

/* ---------- App ---------- */
export default function App() {
  const [aba, setAba] = useState('demandas');
  const [demandas, setDemandas] = useState(seedDemandas);
  const [financas, setFinancas] = useState(seedFinancas);
  const [gastos, setGastos] = useState(seedGastos);
  const [carregado, setCarregado] = useState(false);
  const [session, setSession] = useState(null);
  const [authCarregado, setAuthCarregado] = useState(false);

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      setSession(data.session);
      setAuthCarregado(true);
    });
    const { data: listener } = supabase.auth.onAuthStateChange((_evento, novaSessao) => {
      setSession(novaSessao);
    });
    return () => listener.subscription.unsubscribe();
  }, []);

  async function handleLogout() {
    await supabase.auth.signOut();
  }

  const [erroConexao, setErroConexao] = useState(false);

  async function carregarTudo() {
    try {
      const [{ data: d, error: ed }, { data: f, error: ef }, { data: g, error: eg }] = await Promise.all([
        supabase.from('demandas').select('*').order('prazo', { ascending: true }),
        supabase.from('financas').select('*').order('data_pagamento', { ascending: true }),
        supabase.from('gastos').select('*').order('data', { ascending: true }),
      ]);
      if (ed || ef || eg) throw ed || ef || eg;
      setDemandas((d || []).map(mapDemandaDoBanco));
      setFinancas((f || []).map(mapFinancaDoBanco));
      setGastos((g || []).map(mapGastoDoBanco));
      setErroConexao(false);
    } catch (e) {
      console.error('Erro ao carregar dados do Supabase:', e);
      setErroConexao(true);
    } finally {
      setCarregado(true);
    }
  }

  useEffect(() => {
    if (!session || !supabaseConfigurado) return;
    carregarTudo();

    // Sincronização em tempo real: quando qualquer aparelho muda algo,
    // todos os outros recarregam os dados automaticamente.
    const canal = supabase
      .channel('painel-realtime')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'demandas' }, carregarTudo)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'financas' }, carregarTudo)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'gastos' }, carregarTudo)
      .subscribe();

    return () => { supabase.removeChannel(canal); };
  }, [session]);

  async function criarDemanda(form) {
    const valorBruto = Number(form.valor);
    const { data: demandaInserida, error: erroDemanda } = await supabase
      .from('demandas')
      .insert({
        cliente: form.cliente,
        projeto: form.projeto,
        etapa: form.etapa,
        prazo: form.prazo,
        status: form.status,
        data_gravacao: form.dataGravacao || null,
        datas_gravacao: form.etapa === 'Gravação' ? (form.datasGravacao || []) : [],
        valor: valorBruto,
        com_nf: form.comNF,
      })
      .select()
      .single();
    if (erroDemanda) { alert('Erro ao salvar a demanda: ' + erroDemanda.message); return; }

    const valorLiquido = valorLiquidoTrabalho(valorBruto, form.comNF);
    const { error: erroFinanca } = await supabase.from('financas').insert({
      cliente: form.cliente,
      projeto: form.projeto,
      valor: valorLiquido,
      valor_bruto: valorBruto,
      com_nf: form.comNF,
      data_trabalho: form.prazo,
      data_pagamento: form.dataPagamento || form.prazo,
      pago: false,
      origem_demanda_id: demandaInserida.id,
    });
    if (erroFinanca) alert('Demanda salva, mas houve um erro ao lançar no financeiro: ' + erroFinanca.message);
    carregarTudo();
  }

  async function excluirDemanda(demanda) {
    const { error } = await supabase.from('demandas').delete().eq('id', demanda.id);
    if (error) { alert('Erro ao excluir: ' + error.message); return; }
    carregarTudo();
  }

  async function atualizarDemanda(id, form) {
    const valorBruto = Number(form.valor);
    const { error: erroDemanda } = await supabase
      .from('demandas')
      .update({
        cliente: form.cliente,
        projeto: form.projeto,
        etapa: form.etapa,
        prazo: form.prazo,
        status: form.status,
        data_gravacao: form.dataGravacao || null,
        datas_gravacao: form.etapa === 'Gravação' ? (form.datasGravacao || []) : [],
        valor: valorBruto,
        com_nf: form.comNF,
      })
      .eq('id', id);
    if (erroDemanda) { alert('Erro ao atualizar a demanda: ' + erroDemanda.message); return; }

    const valorLiquido = valorLiquidoTrabalho(valorBruto, form.comNF);
    const { error: erroFinanca } = await supabase
      .from('financas')
      .update({
        cliente: form.cliente,
        projeto: form.projeto,
        valor: valorLiquido,
        valor_bruto: valorBruto,
        com_nf: form.comNF,
        data_trabalho: form.prazo,
        data_pagamento: form.dataPagamento || form.prazo,
      })
      .eq('origem_demanda_id', id);
    if (erroFinanca) alert('Demanda atualizada, mas houve um erro ao atualizar o lançamento financeiro: ' + erroFinanca.message);
    carregarTudo();
  }

  async function criarLancamento(form) {
    const valor = Number(form.valor);
    const { error } = await supabase.from('financas').insert({
      cliente: form.cliente,
      projeto: form.projeto,
      valor,
      valor_bruto: valor,
      com_nf: false,
      data_trabalho: form.dataTrabalho,
      data_pagamento: form.dataPagamento,
      pago: !!form.pago,
    });
    if (error) { alert('Erro ao salvar lançamento: ' + error.message); return; }
    carregarTudo();
  }

  async function atualizarStatusPagamento(f, novoPago) {
    const { error } = await supabase.from('financas').update({ pago: novoPago }).eq('id', f.id);
    if (error) alert('Erro ao atualizar status: ' + error.message);
    carregarTudo();
  }

  async function excluirLancamento(f) {
    const { error } = await supabase.from('financas').delete().eq('id', f.id);
    if (error) { alert('Erro ao excluir: ' + error.message); return; }
    carregarTudo();
  }

  async function criarGasto(form) {
    const { error } = await supabase.from('gastos').insert({
      projeto: form.projeto,
      cliente: form.cliente,
      descricao: form.descricao,
      valor: Number(form.valor),
      data: form.data,
    });
    if (error) { alert('Erro ao salvar gasto: ' + error.message); return; }
    carregarTudo();
  }

  async function excluirGasto(item) {
    const { error } = await supabase.from('gastos').delete().eq('id', item.id);
    if (error) { alert('Erro ao excluir: ' + error.message); return; }
    carregarTudo();
  }

  if (!supabaseConfigurado) {
    return (
      <div style={{ background: '#000000', minHeight: '100vh', color: '#EDEDED', fontFamily: "'Inter', sans-serif" }} className="flex items-center justify-center p-6 text-center">
        <div style={{ maxWidth: 420 }}>
          <p className="mono text-xs tracking-widest mb-2" style={{ color: '#E63946' }}>CONFIGURAÇÃO PENDENTE</p>
          <p className="text-sm" style={{ color: '#9A9A9A' }}>
            Crie um arquivo <code>.env</code> na raiz do projeto com <code>VITE_SUPABASE_URL</code> e{' '}
            <code>VITE_SUPABASE_ANON_KEY</code>. Veja o passo a passo no README.
          </p>
        </div>
      </div>
    );
  }

  if (!authCarregado) {
    return <div style={{ background: '#000000', minHeight: '100vh' }} />;
  }

  if (!session) {
    return <TelaLogin />;
  }

  if (!carregado) {
    return (
      <div style={{ background: '#000000', minHeight: '100vh', color: '#9A9A9A', fontFamily: "'Inter', sans-serif" }} className="flex items-center justify-center">
        <p className="mono text-xs tracking-widest">CARREGANDO DADOS...</p>
      </div>
    );
  }

  return (
    <div style={{ background: '#000000', minHeight: '100%', color: '#EDEDED', fontFamily: "'Inter', sans-serif" }} className="p-5 md:p-8">
      {erroConexao && (
        <div className="mono text-xs rounded p-2 mb-4" style={{ background: '#E639461F', border: '1px solid #E6394655', color: '#E63946' }}>
          Não foi possível sincronizar com o banco de dados agora. Verifique sua internet — tentaremos de novo automaticamente.
        </div>
      )}
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600;700&family=Inter:wght@400;500;600;700&display=swap');
        .mono { font-family: 'IBM Plex Mono', monospace; }
        .card { background: #141414; border: 1px solid #262626; transition: border-color .15s ease, transform .15s ease; }
        .card:hover.hoverable { border-color: #3A3A3A; transform: translateY(-1px); }
        .letterbox { height: 4px; background: #000000; }
        .focusable:focus-visible { outline: 2px solid #F5C518; outline-offset: 2px; }
        select, input, textarea { background: #141414; border: 1px solid #262626; color: #EDEDED; font-family: 'Inter', sans-serif; }
        select:focus, input:focus, textarea:focus { outline: 2px solid #F5C518; outline-offset: 1px; }
        .day-cell { border: 1px solid #1C1C1C; transition: border-color .15s ease, background .15s ease; }
        .day-cell:hover { border-color: #F5C518; cursor: pointer; }
        .badge-btn { cursor: pointer; border: none; }
        .subtab { font-family: 'IBM Plex Mono', monospace; }
      `}</style>

      {/* Header */}
      <div className="flex flex-col gap-4 mb-6">
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-2 sm:gap-3 min-w-0">
            <img src={LOGO_SRC} alt="Norman" className="w-11 h-11 sm:w-16 sm:h-16 rounded-full flex-shrink-0" />
            <div className="min-w-0">
              <div className="hidden sm:flex items-center gap-2 mb-1">
                <span className="mono text-xs tracking-widest" style={{ color: '#9A9A9A' }}>PAINEL DO DIRETOR</span>
              </div>
              <h1 className="mono text-lg sm:text-2xl md:text-3xl font-semibold tracking-tight truncate">Norman Film Crew</h1>
            </div>
          </div>
          <button
            onClick={handleLogout}
            className="focusable mono text-xs font-semibold px-2.5 py-2 rounded flex-shrink-0"
            style={{ background: 'transparent', color: '#9A9A9A', border: '1px solid #262626' }}
            title="Sair"
          >
            Sair
          </button>
        </div>

        <div className="flex items-center justify-between gap-2 flex-wrap">
          <nav className="flex gap-1 p-1 rounded flex-wrap" style={{ background: '#141414', border: '1px solid #262626' }}>
            {[
              { key: 'demandas', label: 'Demandas', icon: LayoutGrid },
              { key: 'agenda', label: 'Agenda', icon: CalendarIcon },
              { key: 'financeiro', label: 'Financeiro', icon: Wallet },
            ].map(({ key, label, icon: Icon }) => (
              <button
                key={key}
                onClick={() => setAba(key)}
                className="focusable mono flex items-center gap-2 px-3 sm:px-4 py-2 rounded text-xs sm:text-sm font-semibold"
                style={{ background: aba === key ? '#F5C518' : 'transparent', color: aba === key ? '#0A0A0A' : '#9A9A9A' }}
              >
                <Icon size={14} /> {label}
              </button>
            ))}
          </nav>
          <span className="mono text-[11px] truncate" style={{ color: '#9A9A9A' }}>{session.user.email}</span>
        </div>
      </div>

      {aba === 'demandas' && <TelaDemandas demandas={demandas} financas={financas} onCriar={criarDemanda} onAtualizar={atualizarDemanda} onExcluir={excluirDemanda} />}
      {aba === 'agenda' && <TelaAgenda demandas={demandas} financas={financas} />}
      {aba === 'financeiro' && <TelaFinanceiro financas={financas} gastos={gastos} demandas={demandas} onCriarLancamento={criarLancamento} onAtualizarStatus={atualizarStatusPagamento} onExcluirLancamento={excluirLancamento} onCriarGasto={criarGasto} onExcluirGasto={excluirGasto} />}
    </div>
  );
}

/* ---------- Seletor de múltiplos dias (usado na gravação) ---------- */
function SeletorDiasMultiplos({ selecionados, onChange }) {
  const [mesAtual, setMesAtual] = useState(new Date());
  const dias = useMemo(() => gerarDias(mesAtual.getFullYear(), mesAtual.getMonth()), [mesAtual]);

  function alternar(chave) {
    if (selecionados.includes(chave)) onChange(selecionados.filter((d) => d !== chave));
    else onChange([...selecionados, chave].sort());
  }

  return (
    <div className="rounded p-2" style={{ border: '1px solid #262626' }}>
      <div className="flex items-center justify-between mb-2">
        <button type="button" onClick={() => setMesAtual(new Date(mesAtual.getFullYear(), mesAtual.getMonth() - 1, 1))} className="focusable p-1" aria-label="Mês anterior">
          <ChevronLeft size={14} color="#9A9A9A" />
        </button>
        <span className="mono text-[11px] tracking-widest">{MESES[mesAtual.getMonth()].toUpperCase()} {mesAtual.getFullYear()}</span>
        <button type="button" onClick={() => setMesAtual(new Date(mesAtual.getFullYear(), mesAtual.getMonth() + 1, 1))} className="focusable p-1" aria-label="Próximo mês">
          <ChevronRight size={14} color="#9A9A9A" />
        </button>
      </div>
      <div className="grid grid-cols-7 gap-1 mb-1">
        {DIAS_SEMANA.map((d, i) => <div key={i} className="mono text-[9px] text-center" style={{ color: '#9A9A9A' }}>{d}</div>)}
      </div>
      <div className="grid grid-cols-7 gap-1">
        {dias.map((d, i) => {
          if (!d) return <div key={i} />;
          const chave = chaveData(d);
          const ativo = selecionados.includes(chave);
          return (
            <button
              type="button"
              key={i}
              onClick={() => alternar(chave)}
              className="focusable mono text-[10px] rounded"
              style={{ padding: '5px 0', background: ativo ? '#F5C518' : 'transparent', color: ativo ? '#0A0A0A' : '#EDEDED', border: '1px solid #262626' }}
            >
              {d.getDate()}
            </button>
          );
        })}
      </div>
      <div className="mono text-[10px] mt-2" style={{ color: '#9A9A9A' }}>
        {selecionados.length === 0 ? 'Nenhum dia selecionado' : `${selecionados.length} dia${selecionados.length === 1 ? '' : 's'} selecionado${selecionados.length === 1 ? '' : 's'}`}
      </div>
    </div>
  );
}

/* ---------- Tela: Demandas ---------- */
function TelaDemandas({ demandas, financas, onCriar, onAtualizar, onExcluir }) {
  const [filtroCliente, setFiltroCliente] = useState('Todos');
  const [filtroStatus, setFiltroStatus] = useState('Todos');
  const [formAberto, setFormAberto] = useState(false);
  const [editando, setEditando] = useState(null);
  const [expandido, setExpandido] = useState(null);
  const [form, setForm] = useState(emptyDemanda);

  const clientes = useMemo(() => ['Todos', ...Array.from(new Set(demandas.map((d) => d.cliente)))], [demandas]);

  const contagem = useMemo(() => {
    const c = { atencao: 0, andamento: 0, aguardando: 0, concluido: 0 };
    demandas.forEach((d) => (c[d.status] += 1));
    return c;
  }, [demandas]);

  const lista = useMemo(() => {
    return demandas
      .filter((d) => filtroCliente === 'Todos' || d.cliente === filtroCliente)
      .filter((d) => filtroStatus === 'Todos' || d.status === filtroStatus)
      .sort((a, b) => diasRestantes(a.prazo) - diasRestantes(b.prazo));
  }, [demandas, filtroCliente, filtroStatus]);

  function abrirNova() {
    setEditando(null);
    setForm(emptyDemanda);
    setFormAberto(true);
  }

  function abrirEdicao(demanda) {
    const financaVinculada = financas.find((f) => f.origemDemandaId === demanda.id);
    setForm({
      cliente: demanda.cliente,
      projeto: demanda.projeto,
      etapa: demanda.etapa,
      prazo: demanda.prazo,
      status: demanda.status,
      dataGravacao: demanda.dataGravacao || null,
      datasGravacao: demanda.datasGravacao || [],
      valor: demanda.valor,
      comNF: demanda.comNF,
      dataPagamento: financaVinculada?.dataPagamento || '',
    });
    setEditando(demanda.id);
    setFormAberto(true);
  }

  function fecharForm() {
    setFormAberto(false);
    setEditando(null);
    setForm(emptyDemanda);
  }

  async function salvar(e) {
    e.preventDefault();
    if (!form.cliente || !form.projeto || !form.prazo || !form.valor) return;
    if (editando) await onAtualizar(editando, form);
    else await onCriar(form);
    fecharForm();
  }

  async function excluir(demanda) {
    const confirmar = window.confirm(`Excluir a demanda "${demanda.projeto}" (${demanda.cliente})?\n\nIsso também remove o lançamento correspondente no Financeiro. Essa ação não pode ser desfeita.`);
    if (!confirmar) return;
    await onExcluir(demanda);
  }

  const maxContagem = Math.max(1, ...Object.values(contagem));

  return (
    <div>
      <div className="flex justify-end mb-4">
        <button onClick={abrirNova} className="focusable flex items-center gap-2 px-4 py-2 rounded mono text-sm font-semibold" style={{ background: '#F5C518', color: '#0A0A0A' }}>
          <Plus size={16} /> Nova demanda
        </button>
      </div>

      <div className="card rounded-lg p-4 md:p-5 mb-6">
        <div className="mono text-xs tracking-widest mb-3" style={{ color: '#9A9A9A' }}>DISTRIBUIÇÃO POR STATUS</div>
        <div className="flex items-end gap-6 h-20">
          {Object.entries(STATUS).map(([key, s]) => (
            <div key={key} className="flex flex-col items-center gap-2 flex-1">
              <div className="w-full flex items-end justify-center" style={{ height: 56 }}>
                <div style={{ width: 28, height: `${Math.max(6, (contagem[key] / maxContagem) * 56)}px`, background: s.color, borderRadius: 2 }} />
              </div>
              <div className="mono text-[11px] text-center" style={{ color: '#9A9A9A' }}>{contagem[key]} · {s.label}</div>
            </div>
          ))}
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-3 mb-6">
        <FilterIcon size={14} color="#9A9A9A" />
        <select value={filtroCliente} onChange={(e) => setFiltroCliente(e.target.value)} className="focusable rounded px-3 py-1.5 text-sm">
          {clientes.map((c) => <option key={c}>{c}</option>)}
        </select>
        <select value={filtroStatus} onChange={(e) => setFiltroStatus(e.target.value)} className="focusable rounded px-3 py-1.5 text-sm">
          <option value="Todos">Todos os status</option>
          {Object.entries(STATUS).map(([key, s]) => <option key={key} value={key}>{s.label}</option>)}
        </select>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {lista.map((d) => {
          const dias = diasRestantes(d.prazo);
          const s = STATUS[d.status];
          const aberto = expandido === d.id;
          const financaVinculada = financas.find((f) => f.origemDemandaId === d.id);
          return (
            <div key={d.id} className="card hoverable rounded-lg overflow-hidden">
              <div className="letterbox" />
              <div className="p-4" style={{ borderLeft: `3px solid ${s.color}` }}>
                <div className="flex items-center justify-between mb-2">
                  <span className="text-xs" style={{ color: '#9A9A9A' }}>{d.cliente}</span>
                  <span className="mono text-xs font-semibold" style={{ color: s.color }}>{prazoLabel(dias)}</span>
                </div>
                <h3 className="font-semibold text-base mb-3">{d.projeto}</h3>
                <div className="flex gap-1 mb-2">
                  {ETAPAS.map((et) => (
                    <div key={et} style={{ flex: 1, height: 4, borderRadius: 2, background: et === d.etapa ? s.color : '#262626' }} title={et} />
                  ))}
                </div>

                <button
                  onClick={() => setExpandido(aberto ? null : d.id)}
                  className="focusable flex items-center justify-between w-full mt-1"
                  aria-expanded={aberto}
                >
                  <span className="mono text-[11px] tracking-wide" style={{ color: '#9A9A9A' }}>{d.etapa.toUpperCase()}</span>
                  <ChevronDown size={14} color="#9A9A9A" style={{ transform: aberto ? 'rotate(180deg)' : 'none', transition: 'transform .15s ease' }} />
                </button>

                {aberto && (
                  <div className="mt-3 pt-3 flex flex-col gap-2" style={{ borderTop: '1px solid #262626' }}>
                    <div className="grid grid-cols-2 gap-2">
                      <div>
                        <div className="mono text-[10px] tracking-widest" style={{ color: '#9A9A9A' }}>VALOR</div>
                        <div className="mono text-sm font-semibold">{moeda(d.valor)}</div>
                        {d.comNF && <div className="mono text-[10px]" style={{ color: '#9A9A9A' }}>líq. {moeda(valorLiquidoTrabalho(d.valor, true))}</div>}
                      </div>
                      <div>
                        <div className="mono text-[10px] tracking-widest" style={{ color: '#9A9A9A' }}>NOTA FISCAL</div>
                        <div className="mono text-sm font-semibold">{d.comNF ? 'Com NF' : 'Sem NF'}</div>
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                      <div>
                        <div className="mono text-[10px] tracking-widest" style={{ color: '#9A9A9A' }}>STATUS</div>
                        <div className="text-sm" style={{ color: s.color }}>{s.label}</div>
                      </div>
                      <div>
                        <div className="mono text-[10px] tracking-widest" style={{ color: '#9A9A9A' }}>DATA DE PAGAMENTO</div>
                        <div className="text-sm">{financaVinculada ? new Date(financaVinculada.dataPagamento + 'T00:00:00').toLocaleDateString('pt-BR') : '—'}</div>
                      </div>
                    </div>
                    {d.etapa === 'Gravação' && d.datasGravacao && d.datasGravacao.length > 0 && (
                      <div>
                        <div className="mono text-[10px] tracking-widest mb-1" style={{ color: '#9A9A9A' }}>DIAS DE GRAVAÇÃO</div>
                        <div className="flex flex-wrap gap-1">
                          {d.datasGravacao.map((data) => (
                            <span key={data} className="mono text-[10px] px-1.5 py-0.5 rounded" style={{ background: '#F5C5181A', border: '1px solid #F5C51855', color: '#F5C518' }}>
                              {new Date(data + 'T00:00:00').toLocaleDateString('pt-BR')}
                            </span>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                )}

                <div className="flex justify-end gap-3 mt-3">
                  <button
                    onClick={() => abrirEdicao(d)}
                    className="focusable flex items-center gap-1 mono text-[11px]"
                    style={{ color: '#9A9A9A' }}
                    title="Editar demanda"
                  >
                    <Pencil size={12} /> Editar
                  </button>
                  <button
                    onClick={() => excluir(d)}
                    className="focusable flex items-center gap-1 mono text-[11px]"
                    style={{ color: '#9A9A9A' }}
                    title="Excluir demanda"
                  >
                    <Trash2 size={12} /> Excluir
                  </button>
                </div>
              </div>
              <div className="letterbox" />
            </div>
          );
        })}
        {lista.length === 0 && <div className="col-span-full text-center py-12 mono text-sm" style={{ color: '#9A9A9A' }}>Nenhuma demanda com esse filtro.</div>}
      </div>

      {formAberto && (
        <div className="fixed inset-0 flex items-start sm:items-center justify-center p-4 overflow-y-auto py-8" style={{ background: 'rgba(0,0,0,0.6)' }}>
          <form onSubmit={salvar} className="card rounded-lg p-6 w-full max-w-sm">
            <div className="flex items-center justify-between mb-4">
              <h2 className="mono text-sm tracking-widest" style={{ color: '#9A9A9A' }}>{editando ? 'EDITAR DEMANDA' : 'NOVA DEMANDA'}</h2>
              <button type="button" onClick={fecharForm} className="focusable" aria-label="Fechar"><X size={18} color="#9A9A9A" /></button>
            </div>
            <div className="flex flex-col gap-3">
              <input required placeholder="Cliente" value={form.cliente} onChange={(e) => setForm({ ...form, cliente: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <input required placeholder="Projeto" value={form.projeto} onChange={(e) => setForm({ ...form, projeto: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <select value={form.etapa} onChange={(e) => setForm({ ...form, etapa: e.target.value })} className="focusable rounded px-3 py-2 text-sm">
                {ETAPAS.map((et) => <option key={et}>{et}</option>)}
              </select>
              {form.etapa === 'Gravação' && (
                <div className="flex flex-col gap-1">
                  <span className="mono text-[11px]" style={{ color: '#9A9A9A' }}>DIAS DE GRAVAÇÃO</span>
                  <SeletorDiasMultiplos
                    selecionados={form.datasGravacao}
                    onChange={(novos) => setForm({ ...form, datasGravacao: novos, prazo: novos.length > 0 ? novos[novos.length - 1] : form.prazo })}
                  />
                </div>
              )}
              {form.etapa !== 'Gravação' && (
                <div className="flex flex-col gap-1">
                  <span className="mono text-[11px]" style={{ color: '#9A9A9A' }}>DATA</span>
                  <input required type="date" value={form.prazo} onChange={(e) => setForm({ ...form, prazo: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
                </div>
              )}
              <select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })} className="focusable rounded px-3 py-2 text-sm">
                {Object.entries(STATUS).map(([key, s]) => <option key={key} value={key}>{s.label}</option>)}
              </select>

              <div className="flex flex-col gap-1">
                <span className="mono text-[11px]" style={{ color: '#9A9A9A' }}>VALOR DO TRABALHO (R$)</span>
                <input required type="number" placeholder="0,00" value={form.valor} onChange={(e) => setForm({ ...form, valor: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              </div>

              <div className="flex flex-col gap-1">
                <span className="mono text-[11px]" style={{ color: '#9A9A9A' }}>NOTA FISCAL</span>
                <div className="flex gap-2">
                  <button
                    type="button"
                    onClick={() => setForm({ ...form, comNF: true })}
                    className="focusable flex-1 mono text-xs font-semibold py-2 rounded"
                    style={{ background: form.comNF ? '#2ECC71' : 'transparent', color: form.comNF ? '#0A0A0A' : '#9A9A9A', border: '1px solid #262626' }}
                  >
                    COM NF (–6%)
                  </button>
                  <button
                    type="button"
                    onClick={() => setForm({ ...form, comNF: false })}
                    className="focusable flex-1 mono text-xs font-semibold py-2 rounded"
                    style={{ background: !form.comNF ? '#8A8F98' : 'transparent', color: !form.comNF ? '#0A0A0A' : '#9A9A9A', border: '1px solid #262626' }}
                  >
                    SEM NF
                  </button>
                </div>
                {form.valor > 0 && (
                  <span className="mono text-[11px] mt-1" style={{ color: '#9A9A9A' }}>
                    Valor a receber: {moeda(valorLiquidoTrabalho(Number(form.valor), form.comNF))}
                  </span>
                )}
              </div>

              <div className="flex flex-col gap-1">
                <span className="mono text-[11px]" style={{ color: '#9A9A9A' }}>DATA DE PAGAMENTO (opcional)</span>
                <input type="date" value={form.dataPagamento} onChange={(e) => setForm({ ...form, dataPagamento: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              </div>

              <button type="submit" className="focusable mono text-sm font-semibold rounded py-2 mt-1" style={{ background: '#F5C518', color: '#0A0A0A' }}>{editando ? 'Salvar alterações' : 'Adicionar'}</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

/* ---------- Tela: Agenda ---------- */
function expandirIntervalo(inicio, fim) {
  const chaves = [];
  let atual = new Date(inicio + 'T00:00:00');
  const final = new Date((fim || inicio) + 'T00:00:00');
  while (atual <= final) {
    chaves.push(chaveData(atual));
    atual = new Date(atual.getFullYear(), atual.getMonth(), atual.getDate() + 1);
  }
  return chaves;
}
const emptyEvento = { titulo: '', cliente: '', tipo: 'gravacao', descricao: '', diaTodo: true, dataInicio: '', dataFim: '', horaInicio: '', horaFim: '', datasSelecionadas: [] };

function TelaAgenda({ demandas, financas }) {
  const [mesAtual, setMesAtual] = useState(() => { const hoje = new Date(); return new Date(hoje.getFullYear(), hoje.getMonth(), 1); });
  const [diaSelecionado, setDiaSelecionado] = useState(null);
  const [eventosManuais, setEventosManuais] = useState([]);
  const [formAberto, setFormAberto] = useState(false);
  const [form, setForm] = useState(emptyEvento);
  const [cores, setCores] = useState(() =>
    Object.fromEntries(Object.entries(TIPO_EVENTO).map(([key, t]) => [key, t.color]))
  );

  const dias = useMemo(() => gerarDias(mesAtual.getFullYear(), mesAtual.getMonth()), [mesAtual]);

  const eventosPorDia = useMemo(() => {
    const map = {};
    const add = (data, ev) => { if (!data) return; if (!map[data]) map[data] = []; map[data].push(ev); };
    demandas.forEach((d) => {
      if (d.etapa === 'Briefing') add(d.prazo, { id: `b-${d.id}`, titulo: `Briefing — ${d.projeto}`, tipo: 'briefing', cliente: d.cliente, diaTodo: true });
      if (d.etapa === 'Gravação') {
        const diasGravacao = (d.datasGravacao && d.datasGravacao.length > 0) ? d.datasGravacao : (d.dataGravacao ? [d.dataGravacao] : [d.prazo]);
        diasGravacao.forEach((data, idx) => add(data, { id: `g-${d.id}-${idx}`, titulo: `Gravação — ${d.projeto}`, tipo: 'gravacao', cliente: d.cliente, diaTodo: true }));
      }
      if (d.etapa === 'Entrega') add(d.prazo, { id: `e-${d.id}`, titulo: `Entrega — ${d.projeto}`, tipo: 'entrega', cliente: d.cliente, diaTodo: true });
    });
    financas.forEach((f) => add(f.dataPagamento, { id: `p-${f.id}`, titulo: `Pagamento — ${f.projeto}`, tipo: 'pagamento', cliente: f.cliente, diaTodo: true }));
    eventosManuais.forEach((ev) => {
      expandirIntervalo(ev.dataInicio, ev.dataFim).forEach((chave) => add(chave, ev));
    });
    return map;
  }, [demandas, financas, eventosManuais]);

  const eventosDoDia = diaSelecionado ? ordenarEventosDia(eventosPorDia[chaveData(diaSelecionado)] || []) : [];

  function trocarMes(delta) {
    setMesAtual(new Date(mesAtual.getFullYear(), mesAtual.getMonth() + delta, 1));
    setDiaSelecionado(null);
  }

  function adicionarTrabalho(e) {
    e.preventDefault();
    if (!form.titulo || !form.cliente) return;

    if (form.tipo === 'gravacao') {
      if (!form.datasSelecionadas || form.datasSelecionadas.length === 0) return;
      const novos = form.datasSelecionadas.map((data, idx) => ({
        id: `m-${Date.now()}-${idx}`,
        titulo: form.titulo,
        cliente: form.cliente,
        tipo: form.tipo,
        descricao: form.descricao,
        diaTodo: true,
        dataInicio: data,
        dataFim: data,
      }));
      setEventosManuais((prev) => [...prev, ...novos]);
      const primeira = new Date(form.datasSelecionadas[0] + 'T00:00:00');
      setDiaSelecionado(primeira);
      setMesAtual(new Date(primeira.getFullYear(), primeira.getMonth(), 1));
    } else {
      if (!form.dataInicio) return;
      const novo = { ...form, dataFim: form.dataFim || form.dataInicio, id: `m-${Date.now()}` };
      setEventosManuais((prev) => [...prev, novo]);
      const inicio = new Date(novo.dataInicio + 'T00:00:00');
      setDiaSelecionado(inicio);
      setMesAtual(new Date(inicio.getFullYear(), inicio.getMonth(), 1));
    }

    setForm(emptyEvento);
    setFormAberto(false);
  }

  function excluirEvento(ev) {
    const confirmar = window.confirm(`Excluir o evento "${ev.titulo}"? Essa ação não pode ser desfeita.`);
    if (!confirmar) return;
    setEventosManuais((prev) => prev.filter((e) => e.id !== ev.id));
  }

  return (
    <div>
      <div className="flex justify-end mb-4">
        <button onClick={() => setFormAberto(true)} className="focusable flex items-center gap-2 px-4 py-2 rounded mono text-sm font-semibold" style={{ background: '#F5C518', color: '#0A0A0A' }}>
          <Plus size={16} /> Novo trabalho
        </button>
      </div>
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        <div className="card rounded-lg p-2 sm:p-4 md:p-5 lg:col-span-2">
          <div className="flex items-center justify-between mb-4">
            <button onClick={() => trocarMes(-1)} className="focusable p-1 rounded" aria-label="Mês anterior"><ChevronLeft size={20} color="#9A9A9A" /></button>
            <span
              className="mono text-lg md:text-xl font-bold tracking-widest px-4 py-1.5 rounded"
              style={{ background: '#F5C5181A', border: '1px solid #F5C51855', color: '#F5C518' }}
            >
              {MESES[mesAtual.getMonth()].toUpperCase()} {mesAtual.getFullYear()}
            </span>
            <button onClick={() => trocarMes(1)} className="focusable p-1 rounded" aria-label="Próximo mês"><ChevronRight size={20} color="#9A9A9A" /></button>
          </div>
          <div className="grid grid-cols-7 gap-1 mb-1">
            {DIAS_SEMANA.map((d, i) => <div key={i} className="mono text-[11px] text-center py-1" style={{ color: '#9A9A9A' }}>{d}</div>)}
          </div>
          <div className="grid grid-cols-7 gap-1">
            {dias.map((d, i) => {
              if (!d) return <div key={i} />;
              const chave = chaveData(d);
              const eventos = ordenarEventosDia(eventosPorDia[chave] || []);
              const selecionado = diaSelecionado && chaveData(diaSelecionado) === chave;
              const visiveis = eventos.slice(0, 2);
              const restante = eventos.length - visiveis.length;
              return (
                <div
                  key={i}
                  onClick={() => setDiaSelecionado(d)}
                  className="day-cell rounded p-0.5 sm:p-1 flex flex-col items-stretch min-h-[56px] sm:min-h-[92px]"
                  style={{ background: selecionado ? 'rgba(245,197,24,0.08)' : 'transparent', borderColor: selecionado ? '#F5C518' : '#1C1C1C' }}
                >
                  <span className="mono text-[10px] sm:text-xs px-0.5" style={{ color: '#9A9A9A' }}>{d.getDate()}</span>
                  <div className="flex flex-col gap-0.5 mt-0.5 sm:mt-1">
                    {visiveis.map((ev) => {
                      const bg = cores[ev.tipo] || TIPO_EVENTO[ev.tipo].color;
                      return (
                        <div
                          key={ev.id}
                          className="mono truncate"
                          style={{ background: bg, color: corTexto(bg), fontSize: 8, lineHeight: '13px', borderRadius: 3, padding: '0 3px' }}
                          title={ev.diaTodo === false ? `${ev.horaInicio || ''} ${ev.titulo}` : ev.titulo}
                        >
                          {ev.diaTodo === false && ev.horaInicio ? `${ev.horaInicio} ` : ''}{ev.titulo}
                        </div>
                      );
                    })}
                    {restante > 0 && (
                      <div className="mono px-1" style={{ fontSize: 8, color: '#9A9A9A' }}>+{restante}</div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
          <div className="flex gap-4 mt-4 flex-wrap items-center">
            {Object.entries(TIPO_EVENTO).map(([key, t]) => (
              <label key={key} className="flex items-center gap-1.5 cursor-pointer">
                <input
                  type="color"
                  value={cores[key]}
                  onChange={(e) => setCores({ ...cores, [key]: e.target.value })}
                  className="focusable"
                  style={{ width: 16, height: 16, padding: 0, border: 'none', borderRadius: 4, background: 'transparent', cursor: 'pointer' }}
                  title={`Cor de ${t.label}`}
                />
                <span className="mono text-[11px]" style={{ color: '#9A9A9A' }}>{t.label}</span>
              </label>
            ))}
          </div>
        </div>

        <div className="card rounded-lg p-4 md:p-5">
          <div className="mono text-xs tracking-widest mb-3" style={{ color: '#9A9A9A' }}>
            {diaSelecionado ? `${diaSelecionado.getDate()} DE ${MESES[diaSelecionado.getMonth()].toUpperCase()}` : 'SELECIONE UM DIA'}
          </div>
          {diaSelecionado && eventosDoDia.length === 0 && <p className="text-sm" style={{ color: '#9A9A9A' }}>Nenhum evento nesse dia.</p>}
          <div className="flex flex-col gap-3">
            {eventosDoDia.map((ev) => {
              const cor = cores[ev.tipo] || TIPO_EVENTO[ev.tipo].color;
              const manual = typeof ev.id === 'string' && ev.id.startsWith('m-');
              return (
                <div key={ev.id} className="pl-3 flex items-start justify-between gap-2" style={{ borderLeft: `3px solid ${cor}` }}>
                  <div>
                    <div className="text-sm font-semibold">{ev.titulo}</div>
                    <div className="text-xs" style={{ color: '#9A9A9A' }}>{ev.cliente}</div>
                    <div className="mono text-[11px] mt-1" style={{ color: cor }}>
                      {ev.diaTodo === false ? `${ev.horaInicio || '--:--'} – ${ev.horaFim || '--:--'}` : 'DIA TODO'}
                    </div>
                    {ev.descricao && <p className="text-xs mt-1" style={{ color: '#9A9A9A' }}>{ev.descricao}</p>}
                  </div>
                  {manual && (
                    <button onClick={() => excluirEvento(ev)} className="focusable flex-shrink-0" title="Excluir evento" style={{ color: '#9A9A9A' }}>
                      <Trash2 size={13} />
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {formAberto && (
        <div className="fixed inset-0 flex items-start sm:items-center justify-center p-4 overflow-y-auto py-8" style={{ background: 'rgba(0,0,0,0.6)' }}>
          <form onSubmit={adicionarTrabalho} className="card rounded-lg p-6 w-full max-w-sm">
            <div className="flex items-center justify-between mb-4">
              <h2 className="mono text-sm tracking-widest" style={{ color: '#9A9A9A' }}>NOVO TRABALHO</h2>
              <button type="button" onClick={() => setFormAberto(false)} className="focusable" aria-label="Fechar"><X size={18} color="#9A9A9A" /></button>
            </div>
            <div className="flex flex-col gap-3">
              <input required placeholder="Título" value={form.titulo} onChange={(e) => setForm({ ...form, titulo: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <input required placeholder="Cliente" value={form.cliente} onChange={(e) => setForm({ ...form, cliente: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <select value={form.tipo} onChange={(e) => setForm({ ...form, tipo: e.target.value })} className="focusable rounded px-3 py-2 text-sm">
                {Object.entries(TIPO_EVENTO_FORM).map(([key, t]) => <option key={key} value={key}>{t.label}</option>)}
              </select>
              <textarea placeholder="Descrição do trabalho" value={form.descricao} onChange={(e) => setForm({ ...form, descricao: e.target.value })} rows={3} className="focusable rounded px-3 py-2 text-sm resize-none" />

              {form.tipo === 'gravacao' ? (
                <div className="flex flex-col gap-1">
                  <span className="mono text-[11px]" style={{ color: '#9A9A9A' }}>DIAS DE GRAVAÇÃO</span>
                  <SeletorDiasMultiplos
                    selecionados={form.datasSelecionadas}
                    onChange={(novos) => setForm({ ...form, datasSelecionadas: novos })}
                  />
                </div>
              ) : (
                <>
                  <label className="flex items-center gap-2 text-sm mono" style={{ color: '#9A9A9A' }}>
                    <input type="checkbox" checked={form.diaTodo} onChange={(e) => setForm({ ...form, diaTodo: e.target.checked })} style={{ accentColor: '#F5C518' }} />
                    Dia todo
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    <div className="flex flex-col gap-1">
                      <span className="mono text-[11px]" style={{ color: '#9A9A9A' }}>INÍCIO</span>
                      <input required type="date" value={form.dataInicio} onChange={(e) => setForm({ ...form, dataInicio: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
                    </div>
                    <div className="flex flex-col gap-1">
                      <span className="mono text-[11px]" style={{ color: '#9A9A9A' }}>FIM</span>
                      <input type="date" value={form.dataFim} onChange={(e) => setForm({ ...form, dataFim: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
                    </div>
                  </div>
                  {!form.diaTodo && (
                    <div className="grid grid-cols-2 gap-2">
                      <div className="flex flex-col gap-1">
                        <span className="mono text-[11px]" style={{ color: '#9A9A9A' }}>HORA INÍCIO</span>
                        <input required type="time" value={form.horaInicio} onChange={(e) => setForm({ ...form, horaInicio: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
                      </div>
                      <div className="flex flex-col gap-1">
                        <span className="mono text-[11px]" style={{ color: '#9A9A9A' }}>HORA FIM</span>
                        <input required type="time" value={form.horaFim} onChange={(e) => setForm({ ...form, horaFim: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
                      </div>
                    </div>
                  )}
                </>
              )}
              <button type="submit" className="focusable mono text-sm font-semibold rounded py-2 mt-1" style={{ background: '#F5C518', color: '#0A0A0A' }}>Adicionar</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

/* ---------- Tela: Financeiro ---------- */
function TelaFinanceiro({ financas, gastos, demandas, onCriarLancamento, onAtualizarStatus, onExcluirLancamento, onCriarGasto, onExcluirGasto }) {
  const [subAba, setSubAba] = useState('receber');
  const [formAberto, setFormAberto] = useState(false);
  const [form, setForm] = useState(emptyFinanca);

  const resumo = useMemo(() => {
    const aReceber = financas.filter((f) => statusFinanceiro(f) !== 'pago').reduce((s, f) => s + (f.valorBruto ?? f.valor), 0);
    const recebido = financas.filter((f) => f.pago).reduce((s, f) => s + (f.valorBruto ?? f.valor), 0);
    const atrasado = financas.filter((f) => statusFinanceiro(f) === 'atrasado').reduce((s, f) => s + (f.valorBruto ?? f.valor), 0);
    return { aReceber, recebido, atrasado };
  }, [financas]);

  const lista = useMemo(() => {
    return financas
      .filter((f) => (subAba === 'concluidos' ? statusFinanceiro(f) === 'pago' : statusFinanceiro(f) !== 'pago'))
      .sort((a, b) => new Date(a.dataPagamento) - new Date(b.dataPagamento));
  }, [financas, subAba]);

  const dadosGrafico = useMemo(() => {
    const chaves = new Set();
    financas.forEach((f) => { if (f.pago) chaves.add(mesChave(f.dataPagamento)); });
    gastos.forEach((g) => chaves.add(mesChave(g.data)));
    return Array.from(chaves).sort().map((chave) => ({
      mes: mesLabelCurto(chave),
      entrada: financas.filter((f) => f.pago && mesChave(f.dataPagamento) === chave).reduce((s, f) => s + (f.valorBruto ?? f.valor), 0),
      saida: gastos.filter((g) => mesChave(g.data) === chave).reduce((s, g) => s + g.valor, 0),
    }));
  }, [financas, gastos]);

  async function mudarStatus(f, novoStatus) {
    await onAtualizarStatus(f, novoStatus === 'pago');
  }

  async function excluirLancamento(f) {
    const confirmar = window.confirm(`Excluir o lançamento de "${f.projeto}" (${f.cliente})? Essa ação não pode ser desfeita.`);
    if (!confirmar) return;
    await onExcluirLancamento(f);
  }

  async function adicionar(e) {
    e.preventDefault();
    if (!form.cliente || !form.projeto || !form.valor || !form.dataTrabalho || !form.dataPagamento) return;
    await onCriarLancamento(form);
    setForm(emptyFinanca);
    setFormAberto(false);
  }

  return (
    <div>
      {subAba !== 'gastos' && (
        <div className="flex justify-end mb-4">
          <button onClick={() => setFormAberto(true)} className="focusable flex items-center gap-2 px-4 py-2 rounded mono text-sm font-semibold" style={{ background: '#F5C518', color: '#0A0A0A' }}>
            <Plus size={16} /> Novo lançamento
          </button>
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
        <div className="card rounded-lg p-4">
          <div className="mono text-xs tracking-widest mb-2" style={{ color: '#9A9A9A' }}>A RECEBER</div>
          <div className="mono text-2xl font-semibold" style={{ color: '#F5C518' }}>{moeda(resumo.aReceber)}</div>
        </div>
        <div className="card rounded-lg p-4">
          <div className="mono text-xs tracking-widest mb-2" style={{ color: '#9A9A9A' }}>RECEBIDO</div>
          <div className="mono text-2xl font-semibold" style={{ color: '#2ECC71' }}>{moeda(resumo.recebido)}</div>
        </div>
        <div className="card rounded-lg p-4">
          <div className="mono text-xs tracking-widest mb-2" style={{ color: '#9A9A9A' }}>ATRASADO</div>
          <div className="mono text-2xl font-semibold" style={{ color: '#E63946' }}>{moeda(resumo.atrasado)}</div>
        </div>
      </div>

      <div className="card rounded-lg p-4 md:p-5 mb-6">
        <div className="mono text-xs tracking-widest mb-3" style={{ color: '#9A9A9A' }}>ENTRADA X SAÍDA POR MÊS</div>
        {dadosGrafico.length === 0 ? (
          <p className="text-sm py-8 text-center" style={{ color: '#9A9A9A' }}>Sem dados suficientes ainda.</p>
        ) : (
          <div style={{ width: '100%', height: 260 }}>
            <ResponsiveContainer>
              <BarChart data={dadosGrafico} barGap={6}>
                <CartesianGrid strokeDasharray="3 3" stroke="#262626" vertical={false} />
                <XAxis dataKey="mes" stroke="#9A9A9A" tick={{ fill: '#9A9A9A', fontSize: 11, fontFamily: 'IBM Plex Mono' }} axisLine={{ stroke: '#262626' }} tickLine={false} />
                <YAxis stroke="#9A9A9A" tick={{ fill: '#9A9A9A', fontSize: 11, fontFamily: 'IBM Plex Mono' }} axisLine={{ stroke: '#262626' }} tickLine={false} tickFormatter={(v) => `${(v / 1000).toFixed(0)}k`} />
                <Tooltip
                  formatter={(v) => moeda(v)}
                  contentStyle={{ background: '#141414', border: '1px solid #262626', borderRadius: 6, fontFamily: 'Inter' }}
                  labelStyle={{ color: '#EDEDED' }}
                  cursor={{ fill: 'rgba(255,255,255,0.03)' }}
                />
                <Legend wrapperStyle={{ fontFamily: 'IBM Plex Mono', fontSize: 11, color: '#9A9A9A' }} />
                <Bar dataKey="entrada" name="Entrada" fill="#2ECC71" radius={[3, 3, 0, 0]} />
                <Bar dataKey="saida" name="Saída" fill="#E63946" radius={[3, 3, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        )}
      </div>

      <div className="flex gap-1 p-1 rounded mb-4 w-fit" style={{ background: '#141414', border: '1px solid #262626' }}>
        {[{ key: 'receber', label: 'A receber' }, { key: 'concluidos', label: 'Concluídos' }, { key: 'gastos', label: 'Gastos' }].map((t) => (
          <button
            key={t.key}
            onClick={() => setSubAba(t.key)}
            className="focusable subtab px-4 py-1.5 rounded text-sm font-semibold"
            style={{ background: subAba === t.key ? '#F5C518' : 'transparent', color: subAba === t.key ? '#0A0A0A' : '#9A9A9A' }}
          >
            {t.label}
          </button>
        ))}
      </div>

      {subAba !== 'gastos' && (
        <div className="card rounded-lg overflow-hidden">
          {/* Cabeçalho — só desktop */}
          <div className="hidden sm:grid grid-cols-12 px-4 py-2 mono text-[11px] tracking-widest" style={{ color: '#9A9A9A', borderBottom: '1px solid #262626' }}>
            <div className="col-span-3">CLIENTE / PROJETO</div>
            <div className="col-span-2">TRABALHO</div>
            <div className="col-span-2">PAGAMENTO</div>
            <div className="col-span-2 text-right">VALOR</div>
            <div className="col-span-2 text-right">STATUS</div>
            <div className="col-span-1 text-right"></div>
          </div>

          {lista.map((f) => {
            const statusKey = statusFinanceiro(f);
            const s = STATUS_FIN[statusKey];
            const statusEl = (
              <>
                <span
                  className="mono text-[11px] font-semibold px-2 py-1 rounded"
                  style={{ color: s.color, background: `${s.color}1F`, border: `1px solid ${s.color}55` }}
                >
                  {s.label.toUpperCase()}
                </span>
                <select
                  value={f.pago ? 'pago' : 'pendente'}
                  onChange={(e) => mudarStatus(f, e.target.value)}
                  className="focusable rounded text-xs py-1"
                  title="Alterar status"
                >
                  <option value="pendente">Pendente</option>
                  <option value="pago">Pago</option>
                </select>
              </>
            );
            return (
              <div key={f.id}>
                {/* Card — só celular */}
                <div className="sm:hidden flex flex-col gap-2 px-4 py-3" style={{ borderBottom: '1px solid #1C1C1C' }}>
                  <div className="flex items-start justify-between">
                    <div>
                      <div className="text-sm font-semibold">{f.cliente}</div>
                      <div className="text-xs" style={{ color: '#9A9A9A' }}>{f.projeto}</div>
                    </div>
                    <button onClick={() => excluirLancamento(f)} className="focusable flex-shrink-0" title="Excluir lançamento" style={{ color: '#9A9A9A' }}>
                      <Trash2 size={14} />
                    </button>
                  </div>
                  <div className="flex justify-between mono text-xs" style={{ color: '#9A9A9A' }}>
                    <span>Trabalho: {new Date(f.dataTrabalho + 'T00:00:00').toLocaleDateString('pt-BR')}</span>
                    <span>Pagto: {new Date(f.dataPagamento + 'T00:00:00').toLocaleDateString('pt-BR')}</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <div>
                      <div className="mono text-sm">{moeda(f.valorBruto ?? f.valor)}</div>
                      {f.comNF && <div className="mono text-[10px]" style={{ color: '#9A9A9A' }}>líq. {moeda(f.valor)}</div>}
                    </div>
                    <div className="flex items-center gap-2">{statusEl}</div>
                  </div>
                </div>

                {/* Linha de tabela — só desktop */}
                <div className="hidden sm:grid grid-cols-12 px-4 py-3 items-center" style={{ borderBottom: '1px solid #1C1C1C' }}>
                  <div className="col-span-3">
                    <div className="text-sm font-semibold">{f.cliente}</div>
                    <div className="text-xs" style={{ color: '#9A9A9A' }}>{f.projeto}</div>
                  </div>
                  <div className="col-span-2 mono text-sm" style={{ color: '#9A9A9A' }}>{new Date(f.dataTrabalho + 'T00:00:00').toLocaleDateString('pt-BR')}</div>
                  <div className="col-span-2 mono text-sm" style={{ color: '#9A9A9A' }}>{new Date(f.dataPagamento + 'T00:00:00').toLocaleDateString('pt-BR')}</div>
                  <div className="col-span-2 text-right">
                    <div className="mono text-sm">{moeda(f.valorBruto ?? f.valor)}</div>
                    {f.comNF && <div className="mono text-[10px]" style={{ color: '#9A9A9A' }}>líq. {moeda(f.valor)}</div>}
                  </div>
                  <div className="col-span-2 flex justify-end items-center gap-2">{statusEl}</div>
                  <div className="col-span-1 flex justify-end">
                    <button onClick={() => excluirLancamento(f)} className="focusable" title="Excluir lançamento" style={{ color: '#9A9A9A' }}>
                      <Trash2 size={14} />
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
          {lista.length === 0 && <div className="text-center py-10 mono text-sm" style={{ color: '#9A9A9A' }}>Nada por aqui ainda.</div>}
        </div>
      )}

      {subAba === 'gastos' && <TelaGastos gastos={gastos} financas={financas} demandas={demandas} onCriar={onCriarGasto} onExcluir={onExcluirGasto} />}

      {formAberto && (
        <div className="fixed inset-0 flex items-start sm:items-center justify-center p-4 overflow-y-auto py-8" style={{ background: 'rgba(0,0,0,0.6)' }}>
          <form onSubmit={adicionar} className="card rounded-lg p-6 w-full max-w-sm">
            <div className="flex items-center justify-between mb-4">
              <h2 className="mono text-sm tracking-widest" style={{ color: '#9A9A9A' }}>NOVO LANÇAMENTO</h2>
              <button type="button" onClick={() => setFormAberto(false)} className="focusable" aria-label="Fechar"><X size={18} color="#9A9A9A" /></button>
            </div>
            <div className="flex flex-col gap-3">
              <input required placeholder="Cliente" value={form.cliente} onChange={(e) => setForm({ ...form, cliente: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <input required placeholder="Projeto" value={form.projeto} onChange={(e) => setForm({ ...form, projeto: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <input required type="number" placeholder="Valor (R$)" value={form.valor} onChange={(e) => setForm({ ...form, valor: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <div className="flex flex-col gap-1">
                <span className="mono text-[11px]" style={{ color: '#9A9A9A' }}>DATA DO TRABALHO</span>
                <input required type="date" value={form.dataTrabalho} onChange={(e) => setForm({ ...form, dataTrabalho: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              </div>
              <div className="flex flex-col gap-1">
                <span className="mono text-[11px]" style={{ color: '#9A9A9A' }}>DATA DO PAGAMENTO</span>
                <input required type="date" value={form.dataPagamento} onChange={(e) => setForm({ ...form, dataPagamento: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              </div>
              <label className="flex items-center gap-2 text-sm mono" style={{ color: '#9A9A9A' }}>
                <input type="checkbox" checked={form.pago} onChange={(e) => setForm({ ...form, pago: e.target.checked })} style={{ accentColor: '#F5C518' }} />
                Já recebido
              </label>
              <button type="submit" className="focusable mono text-sm font-semibold rounded py-2 mt-1" style={{ background: '#F5C518', color: '#0A0A0A' }}>Adicionar</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

/* ---------- Tela: Gastos ---------- */
function TelaGastos({ gastos, financas, demandas, onCriar, onExcluir }) {
  const [formAberto, setFormAberto] = useState(false);
  const [form, setForm] = useState(emptyGasto);

  const projetosDisponiveis = useMemo(() => {
    const map = {};
    financas.forEach((f) => { map[f.projeto] = f.cliente; });
    demandas.forEach((d) => { if (!map[d.projeto]) map[d.projeto] = d.cliente; });
    return Object.entries(map).map(([projeto, cliente]) => ({ projeto, cliente }));
  }, [financas, demandas]);

  const grupos = useMemo(() => {
    const projetos = new Set([...financas.map((f) => f.projeto), ...gastos.map((g) => g.projeto)]);
    return Array.from(projetos).map((projeto) => {
      const financasDoProjeto = financas.filter((f) => f.projeto === projeto);
      const cliente = financasDoProjeto[0]?.cliente || gastos.find((g) => g.projeto === projeto)?.cliente || '—';
      const valorProjeto = financasDoProjeto.reduce((s, f) => s + (f.valorBruto ?? f.valor), 0);
      const valorLiquido = financasDoProjeto.reduce((s, f) => s + f.valor, 0);
      const temNF = financasDoProjeto.some((f) => f.comNF);
      const itens = gastos.filter((g) => g.projeto === projeto);
      const totalGastos = itens.reduce((s, g) => s + g.valor, 0);
      return { projeto, cliente, valorProjeto, valorLiquido, temNF, itens, totalGastos, lucro: valorLiquido - totalGastos };
    }).filter((g) => g.valorProjeto > 0 || g.itens.length > 0);
  }, [financas, gastos]);

  async function adicionar(e) {
    e.preventDefault();
    if (!form.projeto || !form.descricao || !form.valor || !form.data) return;
    const cliente = projetosDisponiveis.find((p) => p.projeto === form.projeto)?.cliente || form.cliente;
    await onCriar({ ...form, cliente });
    setForm(emptyGasto);
    setFormAberto(false);
  }

  async function excluirGasto(item) {
    const confirmar = window.confirm(`Excluir o gasto "${item.descricao}"? Essa ação não pode ser desfeita.`);
    if (!confirmar) return;
    await onExcluir(item);
  }

  return (
    <div>
      <div className="flex justify-end mb-4">
        <button onClick={() => setFormAberto(true)} className="focusable flex items-center gap-2 px-4 py-2 rounded mono text-sm font-semibold" style={{ background: '#F5C518', color: '#0A0A0A' }}>
          <Plus size={16} /> Novo gasto
        </button>
      </div>

      <div className="flex flex-col gap-4">
        {grupos.map((g) => (
          <div key={g.projeto} className="card rounded-lg p-4 md:p-5">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4">
              <div>
                <div className="text-xs" style={{ color: '#9A9A9A' }}>{g.cliente}</div>
                <div className="flex items-center gap-2">
                  <h3 className="font-semibold text-base">{g.projeto}</h3>
                  {g.temNF && (
                    <span
                      className="mono text-[9px] font-semibold px-1.5 py-0.5 rounded"
                      style={{ color: '#8A8F98', background: '#8A8F981F', border: '1px solid #8A8F9555' }}
                    >
                      COM NF
                    </span>
                  )}
                </div>
              </div>
              <div className="grid grid-cols-3 gap-2 sm:gap-5 sm:flex">
                <div>
                  <div className="mono text-[10px] tracking-widest" style={{ color: '#9A9A9A' }}>PROJETO</div>
                  <div className="mono text-xs sm:text-sm font-semibold" style={{ color: '#F5C518' }}>{moeda(g.valorProjeto)}</div>
                  {g.temNF && <div className="mono text-[10px]" style={{ color: '#9A9A9A' }}>líq. {moeda(g.valorLiquido)}</div>}
                </div>
                <div>
                  <div className="mono text-[10px] tracking-widest" style={{ color: '#9A9A9A' }}>GASTOS</div>
                  <div className="mono text-xs sm:text-sm font-semibold" style={{ color: '#E63946' }}>{moeda(g.totalGastos)}</div>
                </div>
                <div>
                  <div className="mono text-[10px] tracking-widest" style={{ color: '#9A9A9A' }}>LUCRO</div>
                  <div className="mono text-xs sm:text-sm font-semibold" style={{ color: g.lucro >= 0 ? '#2ECC71' : '#E63946' }}>{moeda(g.lucro)}</div>
                </div>
              </div>
            </div>

            {g.itens.length > 0 && (
              <div className="flex flex-col gap-2">
                {g.itens.map((item) => (
                  <div key={item.id} className="flex items-center justify-between gap-3 py-2" style={{ borderTop: '1px solid #1C1C1C' }}>
                    <div className="text-sm" style={{ color: '#EDEDED' }}>{item.descricao}</div>
                    <div className="flex items-center gap-3 flex-shrink-0">
                      <span className="mono text-xs" style={{ color: '#9A9A9A' }}>{moeda(item.valor)}</span>
                      <button onClick={() => excluirGasto(item)} className="focusable" title="Excluir gasto" style={{ color: '#9A9A9A' }}>
                        <Trash2 size={13} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
            {g.itens.length === 0 && <p className="text-xs" style={{ color: '#9A9A9A' }}>Nenhum gasto lançado ainda.</p>}
          </div>
        ))}
        {grupos.length === 0 && <div className="card rounded-lg text-center py-12 mono text-sm" style={{ color: '#9A9A9A' }}>Nenhum projeto com dados financeiros ainda.</div>}
      </div>

      {formAberto && (
        <div className="fixed inset-0 flex items-start sm:items-center justify-center p-4 overflow-y-auto py-8" style={{ background: 'rgba(0,0,0,0.6)' }}>
          <form onSubmit={adicionar} className="card rounded-lg p-6 w-full max-w-sm">
            <div className="flex items-center justify-between mb-4">
              <h2 className="mono text-sm tracking-widest" style={{ color: '#9A9A9A' }}>NOVO GASTO</h2>
              <button type="button" onClick={() => setFormAberto(false)} className="focusable" aria-label="Fechar"><X size={18} color="#9A9A9A" /></button>
            </div>
            <div className="flex flex-col gap-3">
              <select required value={form.projeto} onChange={(e) => setForm({ ...form, projeto: e.target.value })} className="focusable rounded px-3 py-2 text-sm">
                <option value="">Selecione o projeto</option>
                {projetosDisponiveis.map((p) => <option key={p.projeto} value={p.projeto}>{p.projeto} — {p.cliente}</option>)}
              </select>
              <input required placeholder="Descrição (ex: freelancer, aluguel de equipamento)" value={form.descricao} onChange={(e) => setForm({ ...form, descricao: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <input required type="number" placeholder="Valor (R$)" value={form.valor} onChange={(e) => setForm({ ...form, valor: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <input required type="date" value={form.data} onChange={(e) => setForm({ ...form, data: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <button type="submit" className="focusable mono text-sm font-semibold rounded py-2 mt-1" style={{ background: '#F5C518', color: '#0A0A0A' }}>Adicionar</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}
